create function public.uuid_generate_v4() returns uuid language sql as $$ select gen_random_uuid() $$;
create table auditoria_eventos (id uuid default gen_random_uuid() not null,ciclo_lote_id uuid,produto_id uuid,usuario_id uuid,acao character varying(50) not null,detalhes jsonb,created_at timestamp with time zone default now(),loja_id uuid);
create table ciclos_lotes (id uuid default gen_random_uuid() not null,codigo_lote character varying(20) not null,loja_id uuid not null,sequencia_num integer not null,status character varying(30) default 'EM EDIÇÃO'::character varying not null,data_abertura timestamp with time zone default now(),data_fechamento timestamp with time zone,fechado_por uuid,enviado_precificacao_por uuid,data_enviado_precificacao timestamp with time zone,created_at timestamp with time zone default now());
create table lojas (id uuid default uuid_generate_v4() not null,nome character varying(255) not null,cnpj character varying(20),created_at timestamp with time zone default now(),razao_social text,inscricao_estadual text,logradouro text,numero text,bairro text,cidade text,uf character varying(2),cep text,telefone text,numero_loja character varying(10) default '01'::character varying);
create table lotes_validade (id uuid default uuid_generate_v4() not null,loja_id uuid not null,produto_id uuid not null,lote character varying(100) not null,data_vencimento date not null,quantidade integer not null,localizacao character varying(100) default 'Gôndola'::character varying,usuario_id uuid,status character varying(20) default 'ativo'::character varying,created_at timestamp with time zone default now(),ciclo_lote_id uuid,tipo_baixa character varying(30),baixado_em timestamp with time zone,lote_origem_codigo character varying(30),origem_cadastro character varying(30) default 'PADRAO'::character varying);
create table perfis (id uuid default gen_random_uuid() not null,loja_id uuid,nome character varying(255) not null,funcao character varying(20) not null,created_at timestamp with time zone default now(),foto_url text);
create table produtos (id uuid default uuid_generate_v4() not null,ean character varying(50) not null,nome character varying(255) not null,categoria character varying(100),created_at timestamp with time zone default now(),imagem_url text,preco_atual numeric(10,2) default 0.00 not null,preco_custo numeric(10,2) default NULL::numeric);
create table usuario_lojas (usuario_id uuid not null,loja_id uuid not null,created_at timestamp with time zone default now());
alter table auditoria_eventos add constraint auditoria_eventos_pkey PRIMARY KEY (id);
alter table ciclos_lotes add constraint ciclos_lotes_codigo_lote_key UNIQUE (codigo_lote);
alter table ciclos_lotes add constraint ciclos_lotes_pkey PRIMARY KEY (id);
alter table ciclos_lotes add constraint ciclos_lotes_status_check CHECK (((status)::text = ANY ((ARRAY['EM EDIÇÃO'::character varying, 'AGUARDANDO CONFERÊNCIA'::character varying, 'ENVIADO PARA PRECIFICAÇÃO'::character varying, 'EM PRECIFICAÇÃO'::character varying, 'REVISADO'::character varying, 'ARQUIVADO'::character varying])::text[])));
alter table lojas add constraint lojas_pkey PRIMARY KEY (id);
alter table lotes_validade add constraint lotes_validade_pkey PRIMARY KEY (id);
alter table lotes_validade add constraint lotes_validade_quantidade_check CHECK ((quantidade >= 0));
alter table lotes_validade add constraint lotes_validade_status_check CHECK (((status)::text = ANY ((ARRAY['ativo'::character varying, 'esgotado'::character varying, 'baixado'::character varying])::text[])));
alter table perfis add constraint perfis_funcao_check CHECK (((funcao)::text = ANY ((ARRAY['administrador'::character varying, 'admin'::character varying, 'gestor'::character varying, 'gerente'::character varying, 'operador'::character varying, 'adm'::character varying, 'precificacao'::character varying])::text[])));
alter table perfis add constraint perfis_pkey PRIMARY KEY (id);
alter table produtos add constraint produtos_ean_key UNIQUE (ean);
alter table produtos add constraint produtos_pkey PRIMARY KEY (id);
alter table usuario_lojas add constraint usuario_lojas_pkey PRIMARY KEY (usuario_id, loja_id);
create function validar_status_lote_para_insercao() returns trigger language plpgsql as $$ declare s text; begin if new.ciclo_lote_id is not null then select status into s from ciclos_lotes where id=new.ciclo_lote_id; if s is distinct from 'EM EDIÇÃO' then raise exception 'Lote não aceita inserção'; end if; end if; return new; end $$;
CREATE TRIGGER trg_validar_status_lote BEFORE INSERT ON public.lotes_validade FOR EACH ROW EXECUTE FUNCTION validar_status_lote_para_insercao();
alter table auditoria_eventos add constraint auditoria_eventos_ciclo_lote_id_fkey FOREIGN KEY (ciclo_lote_id) REFERENCES ciclos_lotes(id) ON DELETE CASCADE;
alter table auditoria_eventos add constraint auditoria_eventos_loja_id_fkey FOREIGN KEY (loja_id) REFERENCES lojas(id) ON DELETE CASCADE;
alter table auditoria_eventos add constraint auditoria_eventos_produto_id_fkey FOREIGN KEY (produto_id) REFERENCES produtos(id) ON DELETE SET NULL;
alter table auditoria_eventos add constraint auditoria_eventos_usuario_id_fkey FOREIGN KEY (usuario_id) REFERENCES perfis(id) ON DELETE SET NULL;
alter table ciclos_lotes add constraint ciclos_lotes_enviado_precificacao_por_fkey FOREIGN KEY (enviado_precificacao_por) REFERENCES perfis(id);
alter table ciclos_lotes add constraint ciclos_lotes_fechado_por_fkey FOREIGN KEY (fechado_por) REFERENCES perfis(id);
alter table ciclos_lotes add constraint ciclos_lotes_loja_id_fkey FOREIGN KEY (loja_id) REFERENCES lojas(id) ON DELETE CASCADE;
alter table lotes_validade add constraint lotes_validade_ciclo_lote_id_fkey FOREIGN KEY (ciclo_lote_id) REFERENCES ciclos_lotes(id) ON DELETE CASCADE;
alter table lotes_validade add constraint lotes_validade_loja_id_fkey FOREIGN KEY (loja_id) REFERENCES lojas(id) ON DELETE CASCADE;
alter table lotes_validade add constraint lotes_validade_produto_id_fkey FOREIGN KEY (produto_id) REFERENCES produtos(id) ON DELETE RESTRICT;
alter table lotes_validade add constraint lotes_validade_usuario_id_fkey FOREIGN KEY (usuario_id) REFERENCES perfis(id);
alter table perfis add constraint perfis_loja_id_fkey FOREIGN KEY (loja_id) REFERENCES lojas(id) ON DELETE RESTRICT;
alter table usuario_lojas add constraint usuario_lojas_loja_id_fkey FOREIGN KEY (loja_id) REFERENCES lojas(id) ON DELETE CASCADE;
alter table usuario_lojas add constraint usuario_lojas_usuario_id_fkey FOREIGN KEY (usuario_id) REFERENCES perfis(id) ON DELETE CASCADE;
